  AND format = '1:1_square_macro_render'

  AND stage_spec = {
    'base': 'thick_hardcover_book',
    'spine_visibility': 'TRUE (facing camera, metallic {{MERGED_TITLE}})',
    'surface': 'dark, non-reflective desk'
  }

  AND lighting_purity = {
