{
  "archetype": "Artistic / Fashion / Conceptual",
  "duration": "15s",
  "prompt": {
    "concept": {
      "title": "CRT Attract – Kinetic Title Sequence",
      "description": "Continuous 15s one-take 1990s arcade attract-mode motion graphics. Five characters already exist as RGB-split glowing outlines on pure black. They keep that exact treatment: black interiors, cyan/magenta/yellow-green channel offset, heavy horizontal CRT scanlines, chromatic aberration, occasional leftward glitch tears. Each holds a characteristic micro-motion inside its original framing. Formation direction alternates every 3s. Morphs only through the RGB outlines tearing, scanning and reforming. Kinetic uppercase arcade text is built from the same RGB-split scanline strokes on the complementary side. Final INSERT COIN. Always raster-alive, never a solid fill, never static.",
      "duration": "15s",
      "rhythm_structure": {
        "0-3s": "[image1] holds + micro-motion, text left",
        "3-6s": "Morph to [image2] + micro-motion, text right",
        "6-9s": "Morph to [image3] + micro-motion, text left",
        "9-12s": "Morph to [image4] + micro-motion, text right",
        "12-15s": "Morph to [image5] + micro-motion + final INSERT COIN"
      }
    },
    "camera_direction": {
      "shot_type": "Strict continuous one-take, locked",
      "forbidden": ["No cuts", "No teleportation", "No hidden transitions", "No freeze frames", "No full-body reframes", "No solid-filled bodies", "No volumetric smoke"],
      "camera_journey": "Centered on pure black void. Locked. All energy from RGB outline jitter, scanline sweep, leftward glitch tears and the morphs. Framing of each character stays as in its reference: chest-up for 1–4, side-profile runner for 5."
    },
    "typography": {
      "allowed_words": [
        "CRT ATTRACT",
        "MOTION GRAPHICS",
        "MIDJOURNEY + H3",
        "PROMPTS by TechHalla",
        "INSERT COIN"
      ],
      "treatment": {
        "not_flat_overlay": true,
        "required_properties": [
          "Built from the same cyan/magenta/yellow RGB-split strokes as the characters",
          "Heavy horizontal scanlines through every letter",
          "Chromatic aberration on the edges, matching the stills",
          "90s arcade slam: scale punch, slight raster bounce, leftward glitch smear on impact",
          "Extra-bold condensed uppercase, Street Fighter / Namco attract energy",
          "Kinetic emergence synchronized to morphs and scanline direction"
        ]
      }
    },
    "visual_style": {
      "overall": "RGB-split CRT outline art on pure black. Characters are glowing wire silhouettes, interiors stay black, scanlines across the whole figure, cyan magenta yellow-green channel offset, horizontal glitch tears. Same look as the five stills, held for 15s.",
      "inspired_by": [
        "[image1] – Chun-Li chest-up, ox-horn buns with ribbons, qipao collar, centered portrait, RGB-split outlines, scanlines, black fill",
        "[image2] – Cloud chest-up, spiky hair, Buster Sword hilt over the right shoulder, dark face and torso, magenta in the hair, cyan on hair tips and hilt, horizontal tears on hair and pauldrons",
        "[image3] – Snake chest-up, facing camera, bandana tails flying right, stubble, tactical collar, cyan-magenta line-art, no fill",
        "[image4] – Lara medium close-up on the right, one pistol held vertical against her cheek, hair tied back, scanlines, leftward smear behind the gun",
        "[image5] – Sonic side-profile facing right, hunched ready-to-run, quills and sneakers in RGB-split strokes, horizontal speed-glitch streaks going left"
      ],
      "color_palette": ["electric cyan", "magenta", "yellow-green", "electron-beam white", "pure black void"],
      "materials_and_texture": "RGB channel-offset line, CRT scanlines, phosphor bloom only on the strokes, horizontal displacement tears, black interiors"
    },
    "motion_language": {
      "follows_music": false,
      "core_behavior": "Never static. Scanlines always travel. RGB channels always breathe a few pixels apart. Morphs happen only by the outlines tearing horizontally and reforming as the next silhouette. Each character stays inside its still's crop. Type slams like a 90s continue screen, made of the same strokes."
    },
    "storyboard": {
      "total_beats": 5,
      "beat_duration": "3 seconds each",
      "beats": [
        {
          "id": "01",
          "time": "0.0–3.0",
          "description": "Pure black. [image1] is already on: Chun-Li chest-up, ox-horn buns, qipao collar, RGB-split outlines, scanlines, black interior. Ribbons on the buns flicker. A micro chin turn. Outline vibration in cyan and magenta. Scanlines crawl down the face. Text “CRT ATTRACT” slams left, same RGB-split scanline strokes, extra-bold uppercase. End of beat: her outline tears horizontally into raw scanlines."
        },
        {
          "id": "02",
          "time": "3.0–6.0",
          "description": "Scanlines reverse left-to-right and lock into [image2]: Cloud chest-up, spiky hair, Buster Sword hilt over the right shoulder, dark face, magenta in the hair, cyan on the tips and hilt. Hair spikes crawl with a horizontal RGB tear. Slow head turn. Hilt catches a scanline. Previous text dissolves. “MOTION GRAPHICS” slams right in the same stroke language. End of beat: hair and hilt tear into scanlines."
        },
        {
          "id": "03",
          "time": "6.0–9.0",
          "description": "Scanlines reverse right-to-left and lock into [image3]: Snake chest-up, facing camera, bandana tails to the right, stubble, tactical collar, cyan-magenta line-art, no fill. Bandana tails flutter. Eyes narrow. RGB split on the bandana widens a few pixels. Text “MIDJOURNEY + H3” slams left. End of beat: the bandana tails tear into scanlines and take the face with them."
        },
        {
          "id": "04",
          "time": "9.0–12.0",
          "description": "Scanlines reverse left-to-right and lock into [image4]: Lara medium close-up on the right, one pistol vertical against her cheek, hair tied back, scanlines, leftward smear already behind the gun. She holds the gun exactly there. A slow breath. The leftward glitch smear pulses. Text “PROMPTS by TechHalla” slams right out of that smear. End of beat: the gun-smear tears her into scanlines."
        },
        {
          "id": "05",
          "time": "12.0–15.0",
          "description": "Scanlines reverse right-to-left and lock into [image5]: Sonic side-profile facing right, hunched ready-to-run, RGB-split quills and sneakers, horizontal speed-glitch streaks already going left. He leans a fraction more into the run. The leftward streaks stretch. Previous text dissolves. Residual outlines briefly reform titles, then “INSERT COIN” slams centered in the same RGB-split scanline strokes as the streaks fade into black, last scanline crossing the word, never fully static until end frame."
        }
      ]
    }
  }
}

